<?php
$page_title='การคืนสินค้าของฉัน';require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$stmt=$db->prepare('SELECT r.*,o.order_no,o.total_amount FROM return_requests r JOIN orders o ON o.id=r.order_id WHERE r.user_id=? ORDER BY r.id DESC');$stmt->execute([(int)$_SESSION['user_id']]);$returns=$stmt->fetchAll();require_once __DIR__.'/includes/header.php';
$labels=['requested'=>'รอตรวจสอบ','approved'=>'อนุมัติแล้ว กรุณาส่งสินค้าคืน','rejected'=>'คำขอถูกปฏิเสธ','received'=>'ร้านได้รับสินค้าคืนแล้ว','refunded'=>'คืนเงินเรียบร้อย','cancelled'=>'ยกเลิก'];$steps=['requested'=>1,'approved'=>2,'received'=>3,'refunded'=>4];
?>
<div class="container" style="margin:36px auto 70px;max-width:900px"><div style="display:flex;justify-content:space-between;align-items:center;gap:16px"><h1><i class="fa-solid fa-arrow-rotate-left"></i> การคืนสินค้า</h1><a class="btn btn-outline" href="<?php echo BASE_URL;?>my-orders.php">คำสั่งซื้อของฉัน</a></div><div style="display:grid;gap:14px;margin-top:24px"><?php if(!$returns):?><section class="checkout-card" style="text-align:center">ยังไม่มีคำขอคืนสินค้า</section><?php endif;?><?php foreach($returns as $r):$items=$db->prepare('SELECT ri.quantity,ri.refund_amount,oi.product_name,oi.variant_name FROM return_request_items ri JOIN order_items oi ON oi.id=ri.order_item_id WHERE ri.return_request_id=?');$items->execute([(int)$r['id']]);$items=$items->fetchAll();$current=$steps[$r['status']]??0;?><article class="checkout-card"><div style="display:flex;justify-content:space-between;gap:12px"><strong><?php echo e($r['order_no']);?></strong><span class="status-badge <?php echo e($r['status']);?>"><?php echo e($labels[$r['status']]??$r['status']);?></span></div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:18px 0"><?php foreach(['ส่งคำขอ','อนุมัติ','รับสินค้าคืน','คืนเงิน'] as $i=>$label):?><span style="padding:8px;text-align:center;background:<?php echo $current>=$i+1?'#173f32':'#eee';?>;color:<?php echo $current>=$i+1?'#fff':'#777';?>;font-size:12px"><?php echo $label;?></span><?php endforeach;?></div><?php foreach($items as $item):?><p style="margin:5px 0"><strong><?php echo e($item['product_name'].($item['variant_name']?' · '.$item['variant_name']:''));?></strong> × <?php echo (int)$item['quantity'];?> · <?php echo formatCurrency($item['refund_amount']);?></p><?php endforeach;?><p><?php echo nl2br(e($r['reason']));?></p><?php if($r['evidence_image']):?><a href="<?php echo e(productImageUrl($r['evidence_image']));?>" target="_blank"><img src="<?php echo e(productImageUrl($r['evidence_image']));?>" alt="หลักฐานคืนสินค้า" style="width:100px;height:100px;object-fit:cover"></a><?php endif;?><?php if($r['admin_note']):?><p><small>หมายเหตุ: <?php echo e($r['admin_note']);?></small></p><?php endif;?><?php if($r['status']==='approved'&&empty($r['return_tracking_number'])):?><form class="return-shipping-form" style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px"><input type="hidden" name="action" value="ship_return"><input type="hidden" name="return_id" value="<?php echo (int)$r['id'];?>"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input name="carrier" placeholder="บริษัทขนส่ง" required><input name="tracking_number" placeholder="เลขพัสดุส่งคืน" required><button class="btn btn-primary">แจ้งส่งสินค้าคืน</button></form><?php elseif($r['return_tracking_number']):?><p><i class="fa-solid fa-truck"></i> <?php echo e($r['return_carrier']);?> · <strong><?php echo e($r['return_tracking_number']);?></strong></p><?php endif;?></article><?php endforeach;?></div></div><script>document.querySelectorAll('.return-shipping-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const r=await fetch(`${BASE_URL}api/returns.php`,{method:'POST',body:new FormData(f)}),j=await r.json();showToast(j.message,j.status==='success'?'success':'error');if(j.status==='success')setTimeout(()=>location.reload(),500)});</script><?php require_once __DIR__.'/includes/footer.php';?>
